solutions.naive:
class Solution:
    def mySqrt(self, x: int) -> int:
        r = 0
        while (r + 1) * (r + 1) <= x:
            r += 1
        return r

solutions.better:
class Solution:
    def mySqrt(self, x: int) -> int:
        if x < 2:
            return x
        guess = x
        while guess * guess > x:
            guess = (guess + x // guess) // 2
        return guess

solutions.optimal:
class Solution:
    def mySqrt(self, x: int) -> int:
        left, right = 0, x
        answer = 0
        while left <= right:
            mid = (left + right) // 2
            square = mid * mid
            if square <= x:
                answer = mid
                left = mid + 1
            else:
                right = mid - 1
        return answer

